
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_jrgx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe_jrgx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.790506654203974e-02, -7.690382442827896e-02, -7.546541241683569e-02, -7.339986379981622e-02, -7.043566113515150e-02, -6.618695986285378e-02, -6.011638763033102e-02, -5.153299635972043e-02, -3.985988513526165e-02, -2.631234255134244e-02, -2.012801856319336e-02, -4.545822330385726e-02, -5.014151044667303e-02, -3.881878794880572e-02, -2.340170019321123e-02, -7.628318830168218e-03, -5.735814261358293e-04, -5.751478548522845e-06, -5.976750030336503e-09, -2.367049310109350e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


